package com.worklink.service;
import com.worklink.dto.project.*; import com.worklink.entity.*; import com.worklink.entity.enums.ProjectStatus; import com.worklink.exception.*; import com.worklink.repository.*; import com.worklink.security.CurrentUserProvider; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProjectService { final ProjectRepository projects; final ProjectSkillRepository projectSkills; final ClientProfileRepository clients; final FreelancerProfileRepository freelancers; final CategoryRepository categories; final SkillRepository skills; final CurrentUserProvider current;
 public ProjectService(ProjectRepository p,ProjectSkillRepository ps,ClientProfileRepository c,FreelancerProfileRepository f,CategoryRepository ca,SkillRepository s,CurrentUserProvider cu){projects=p;projectSkills=ps;clients=c;freelancers=f;categories=ca;skills=s;current=cu;}
 ClientProfile client(){return clients.findByUserId(current.requireCurrentUser().id()).orElseThrow(ProfileNotFoundException::new);} 
 FreelancerProfile freelancer(){return freelancers.findByUserId(current.requireCurrentUser().id()).orElseThrow(ProfileNotFoundException::new);}
 @Transactional public ProjectResponse create(ProjectRequest r){Project p=new Project();p.setClient(client());apply(p,r);p.setStatus(ProjectStatus.DRAFT);return save(p,r);}
 @Transactional public ProjectResponse update(Long id,ProjectRequest r){Project p=owned(id); if(p.getStatus()!=ProjectStatus.DRAFT) throw new IllegalArgumentException("Only draft projects can be edited");apply(p,r);return save(p,r);}
 @Transactional public void delete(Long id){Project p=owned(id);if(p.getStatus()!=ProjectStatus.DRAFT&&p.getStatus()!=ProjectStatus.CANCELLED)throw new IllegalArgumentException("Only draft or cancelled projects can be deleted");projectSkills.deleteByProjectId(id);projects.delete(p);}
 @Transactional public ProjectResponse publish(Long id){Project p=owned(id);if(p.getStatus()!=ProjectStatus.DRAFT)throw new IllegalArgumentException("Only draft projects can be published");if(projectSkills.findByProjectId(id).isEmpty())throw new IllegalArgumentException("A project needs at least one required skill");p.setStatus(ProjectStatus.PUBLISHED);return response(projects.save(p));}
 @Transactional(readOnly=true) public List<ProjectResponse> mine(){return projects.findByClientId(client().getId()).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public ProjectResponse mine(Long id){return response(owned(id));}
 @Transactional(readOnly=true) public List<ProjectResponse> published(){return projects.findByStatus(ProjectStatus.PUBLISHED).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<ProjectResponse> active(){return projects.findByClientId(client().getId()).stream().filter(p->p.getAcceptedFreelancer()!=null).map(this::response).toList();}
 @Transactional(readOnly=true) public List<ProjectResponse> activeForFreelancer(){return projects.findByAcceptedFreelancerId(freelancer().getId()).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public ProjectResponse published(Long id){Project p=projects.findById(id).filter(x->x.getStatus()==ProjectStatus.PUBLISHED).orElseThrow(()->new ResourceNotFoundException("Project not found"));return response(p);}
 void apply(Project p,ProjectRequest r){if(r.budgetMax().compareTo(r.budgetMin())<0)throw new IllegalArgumentException("Maximum budget must not be less than minimum budget");p.setTitle(r.title().trim());p.setDescription(r.description().trim());p.setCategory(categories.findById(r.categoryId()).orElseThrow(()->new ResourceNotFoundException("Category not found")));p.setRequiredExperience(r.requiredExperience());p.setBudgetMin(r.budgetMin());p.setBudgetMax(r.budgetMax());p.setDeadline(r.deadline());p.setComplexity(r.complexity());p.setDeliverables(r.deliverables()==null?null:r.deliverables().trim());}
 ProjectResponse save(Project p,ProjectRequest r){Set<Long> ids=new HashSet<>();for(var s:r.skills())if(!ids.add(s.skillId()))throw new DuplicateResourceException("A skill can only be added once to a project");p=projects.save(p);projectSkills.deleteByProjectId(p.getId());projectSkills.flush();for(var x:r.skills()){Skill s=skills.findById(x.skillId()).orElseThrow(()->new ResourceNotFoundException("Skill not found"));projectSkills.save(new ProjectSkill(p,s,x.importance()));}return response(p);}
 Project owned(Long id){return projects.findByIdAndClientId(id,client().getId()).orElseThrow(()->new ResourceNotFoundException("Project not found"));}
 ProjectResponse response(Project p){var accepted=p.getAcceptedFreelancer();return new ProjectResponse(p.getId(),p.getTitle(),p.getDescription(),p.getCategory().getId(),p.getCategory().getName(),p.getClient().getCompanyName(),p.getRequiredExperience(),p.getBudgetMin(),p.getBudgetMax(),p.getDeadline(),p.getComplexity().name(),p.getDeliverables(),p.getStatus().name(),accepted==null?null:accepted.getId(),accepted==null?null:accepted.getUser().getFirstName()+" "+accepted.getUser().getLastName(),p.getCreatedAt(),p.getUpdatedAt(),projectSkills.findByProjectId(p.getId()).stream().map(x->new ProjectResponse.Skill(x.getSkill().getId(),x.getSkill().getName(),x.getImportance().name())).toList());}}
